const input=document.querySelector('#input'),bubble=document.querySelector('#userBubble'),form=document.querySelector('#composer');document.querySelectorAll('.recent-row').forEach(row=>row.addEventListener('click',()=>{document.querySelectorAll('.recent-row').forEach(x=>x.classList.remove('selected'));row.classList.add('selected');document.querySelector('#title').textContent=row.textContent.trim()}));form.addEventListener('submit',e=>{e.preventDefault();const value=input.value.trim();if(!value)return;bubble.textContent=value;document.querySelector('#title').textContent=value;input.value=''});document.querySelector('#plus').addEventListener('click',()=>input.focus());document.querySelectorAll('.tool-list button').forEach(button=>button.addEventListener('click',()=>button.animate([{opacity:.45},{opacity:1}],{duration:250})));
